import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 30, B: 50, C: 19.99, D: 101, E: 100, F: 1.15 }

async function withApp(fn) {
  const server = createServer(createApp({ pricing: { priceOf: async (sku) => prices[sku] } }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(base, items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// Characterization tests: they pin CURRENT behaviour, including questionable parts
// (see "CURRENT BEHAVIOUR" notes). Update them deliberately if the rules change.
const cases = [
  ['sums unit price * qty across items', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], 110 * 0.9 - 0.9 /* 99 */],
  ['no discount below threshold', [{ sku: 'A', qty: 3 }], 90],
  ['no discount at exactly 100 (threshold is strictly >100)', [{ sku: 'E', qty: 1 }], 100],
  ['10% discount just above threshold, floored (90.9 -> 90)', [{ sku: 'D', qty: 1 }], 90],
  ['10% discount on a larger order', [{ sku: 'A', qty: 10 }], 270],
  ['10% discount on a much larger order', [{ sku: 'B', qty: 100 }], 4500],
  ['CURRENT BEHAVIOUR: cents are floored away without discount (59.97 -> 59)', [{ sku: 'C', qty: 3 }], 59],
  ['CURRENT BEHAVIOUR: floating point error can lose a whole unit (1.15*100 -> 114.99.. *0.9)', [{ sku: 'F', qty: 100 }], 103],
]

for (const [name, items, expected] of cases) {
  test(name, () => withApp(async (base) => {
    assert.equal(await totalFor(base, items), expected)
  }))
}

test('order can be fetched back with the same total', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'A', qty: 10 }] }) })
  const { id } = await res.json()
  const got = await (await fetch(`${base}/orders/${id}`)).json()
  assert.equal(got.total, 270)
}))

test('rejects empty orders', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
}))
EOF
sed -i "s|110 \* 0.9 - 0.9 /\* 99 \*/|99|" test/order-total.test.mjs
node --test 2>&1 | grep -E "^# (pass|fail)|not ok|expected|actual"

